#include "auth.h"
#include "file_manager.h"
#include "encryption.h"
#include "audit_log.h"
#include "access_control.h"
#include <iostream>
namespace secureos {
static std::string ask(const std::string&s){std::cout<<s;std::string x;std::getline(std::cin,x);return x;}
static int menu(const std::string& title,const std::string& choices){std::cout<<"\n+------------------------------------------------+\n| "<<title<<"\n+------------------------------------------------+\n"<<choices<<"Choice: ";std::string s;std::getline(std::cin,s);try{size_t p;int n=std::stoi(s,&p);return p==s.size()?n:-1;}catch(...){return -1;}}
void runUI(const std::filesystem::path& data) {
 AuditLog log(data);AuthService auth(data,log);FileManager files(data,log);EncryptionService crypto(data,log);
 while(std::cin){int c=menu("SecureOS | Security Simulator","1. Login\n2. Register\n3. System Status\n0. Exit\n");if(c==0)break;if(c==2){std::string m;auth.registerUser(ask("Username: "),ask("Password (10+ characters): "),m);std::cout<<m<<"\n";continue;}if(c==3){std::cout<<"Users: "<<auth.allUsers().size()<<" | Managed files: "<<files.list().size()<<"\nThis is an educational user-space simulator, not an operating system.\n";continue;}if(c!=1){std::cout<<"Invalid choice.\n";continue;}std::string m;auto active=auth.login(ask("Username: "),ask("Password: "),m);std::cout<<m<<"\n";if(!active)continue;
  bool logged=true;while(logged&&std::cin){int d=menu("Dashboard | "+active->name+" ("+roleName(active->role)+")","1. File Manager\n2. Access Permissions\n3. Encrypt / Decrypt File\n4. Security Audit Logs\n5. Change Password\n6. User Management (Admin only)\n0. Logout\n");if(d==0){log.record(active->name,"logout");logged=false;continue;}if(d==1){int f=menu("File Manager","1. List files\n2. Create text file\n3. Read file\n4. Edit file\n5. Delete file\n0. Back\n");std::string n,content;if(f==1){for(auto&x:files.list())std::cout<<"- "<<x<<" | owner: "<<files.ownerOf(x)<<" | permissions: role policy\n";}else if(f==2){n=ask("Filename: ");content=ask("One-line content: ");files.create(*active,n,content,m);std::cout<<m<<"\n";}else if(f==3){n=ask("Filename: ");if(files.read(*active,n,content,m))std::cout<<"---\n"<<content<<"\n---\n";else std::cout<<m<<"\n";}else if(f==4){n=ask("Filename: ");content=ask("Replacement one-line content: ");files.edit(*active,n,content,m);std::cout<<m<<"\n";}else if(f==5){n=ask("Filename: ");if(ask("Type YES to delete: ")=="YES")files.remove(*active,n,m);else m="Cancelled.";std::cout<<m<<"\n";}else if(f!=0)std::cout<<"Invalid choice.\n";}else if(d==2){std::cout<<"Role permissions: Admin all actions; Editor read/create/edit/encrypt/decrypt/view logs; Viewer read only.\n";}else if(d==3){int e=menu("Encryption","1. Encrypt\n2. Decrypt\n0. Back\n");std::string key;if(e==1){if(crypto.encrypt(*active,ask("Input filename: "),ask("New encrypted filename: "),key,m))std::cout<<m<<"\nKEY (shown once; store safely): "<<key<<"\n";else std::cout<<m<<"\n";}else if(e==2){crypto.decrypt(*active,ask("Encrypted filename: "),ask("New output filename: "),ask("64-character hex key: "),m);std::cout<<m<<"\n";}else if(e!=0)std::cout<<"Invalid choice.\n";}else if(d==4){if(!allowed(active->role,Action::ViewLogs)){std::cout<<"Access denied.\n";log.record(active->name,"denied audit view");}else for(auto&x:log.readAll())std::cout<<x<<"\n";}else if(d==5){auth.changePassword(active->name,ask("Current password: "),ask("New password: "),m);std::cout<<m<<"\n";}else if(d==6){std::cout<<"Users:\n";for(auto&u:auth.allUsers())std::cout<<u.name<<" - "<<roleName(u.role)<<"\n";std::string r=ask("Target role (Admin/Editor/Viewer; blank to cancel): ");if(!r.empty()){Role role=r=="Admin"?Role::Admin:r=="Editor"?Role::Editor:Role::Viewer;auth.setRole(*active,ask("Target username: "),role,m);std::cout<<m<<"\n";}}else std::cout<<"Invalid choice.\n";
  }
 }
}
}
